/** Every cell adjacent to a live cell, mapped to how many live neighbors it has. */
function countLiveNeighbors(cells: Cell[]): Map<string, { cell: Cell; count: number }> {
  const counts = new Map<string, { cell: Cell; count: number }>();
  for (const [x, y] of cells) {
    for (const neighbor of neighbors(x, y)) {
      const entry = counts.get(key(...neighbor)) ?? { cell: neighbor, count: 0 };
      entry.count += 1;
      counts.set(key(...neighbor), entry);
    }
  }
  return counts;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map((cell) => key(...cell)));

  const nextLiving: Cell[] = [];
  for (const [cellKey, { cell, count }] of countLiveNeighbors(cells)) {
    const isAlive = living.has(cellKey);
    if (count === 3 || (isAlive && count === 2)) nextLiving.push(cell);
  }
  return nextLiving;
}

